def swap_and_aggregate(data_dict):
    # Write your solution here
    res = {}
    for k, v in data_dict.items():
        if v not in res:
            res[v] = [k]
        else:
            res[v].append(k)
    return {k: sorted(v) if len(v) > 1 else v[0] for k, v in res.items()}

